public interface INotifier { Task SendAsync(string message); }
public class EmailNotifier : INotifier
{
    private readonly SmtpClient _client;
    public EmailNotifier(SmtpClient client) => _client = client;
    public async Task SendAsync(string message) => await _client.SendMailAsync(message);
}

// Registration
builder.Services.AddTransient<INotifier, EmailNotifier>();

// Usage in a controller
public class FeedbackController(INotifier notifier) : Controller
{
    public async Task<IActionResult> Submit(string feedback)
    {
        await notifier.SendAsync(feedback); // new instance here
        await notifier.SendAsync(feedback); // another new instance
        return Ok();
    }
}

builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("Default")));

// Inside a request, all services that inject AppDbContext share one instance:
public class OrdersController(AppDbContext db) : Controller
{
    public async Task<IActionResult> Index()
    {
        var orders = await db.Orders.ToListAsync(); // uses the scoped db
        return View(orders);
    }
}

public class ProductsController(AppDbContext db) : Controller
{
    public async Task<IActionResult> Index()
    {
        var products = await db.Products.ToListAsync(); // same scoped db
        return View(products);
    }
}

public interface ICacheService { T Get<T>(string key); void Set<T>(string key, T value); }
public class InMemoryCacheService : ICacheService
{
    private readonly MemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    public T Get<T>(string key) => _cache.Get<T>(key);
    public void Set<T>(string key, T value) => _cache.Set(key, value);
}

// Registration
builder.Services.AddSingleton<ICacheService, InMemoryCacheService>();

// Every request shares the same cache instance:
public class WeatherController(ICacheService cache) : Controller
{
    public IActionResult Forecast()
    {
        var forecast = cache.Get<Forecast>("today");
        if (forecast == null)
        {
            forecast = _weatherService.GetToday();
            cache.Set("today", forecast);
        }
        return Ok(forecast);
    }
}
